WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, attributes, COALESCE(attributes['gift'], 'none') AS gift_or_default, SIZE(attributes) AS num_attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, TRANSFORM(items, x -> x.product_id) AS product_ids, SIZE(items) AS num_items FROM carts) SELECT *, LEAD(num_attributes, 1, 0) OVER (PARTITION BY customer_id ORDER BY num_attributes ASC, id ASC) AS next_num_attributes, AVG(weight_kg) OVER (PARTITION BY YEAR(created_at) ORDER BY CAST(created_at AS BIGINT) ASC RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS weight_kg_avg_2h, SUM(weight_kg) OVER (PARTITION BY TO_DATE(created_at) ORDER BY num_attributes ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_weight_kg, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY weight_kg DESC, id ASC) AS event_seq FROM flattened_attrs;
